const requeueStalled = `-- name: RequeueStalled :many
UPDATE meetings
SET status = 'queued', run_id = gen_random_uuid(), heartbeat_at = NULL,
    stage = '', progress = 0, requeues = requeues + 1, updated_at = now()
WHERE status = 'processing'
  AND heartbeat_at < now() - make_interval(secs => $1::int)
  AND requeues < $2::int
RETURNING id, run_id
`

type RequeueStalledParams struct {
	StaleSecs   int32
	MaxRequeues int32
}

type RequeueStalledRow struct {
	ID    uuid.UUID
	RunID *uuid.UUID
}

// 心跳停了的会议换一个 run_id 重新入队；旧任务即使还活着也写不进去了
func (q *Queries) RequeueStalled(ctx context.Context, arg RequeueStalledParams) ([]RequeueStalledRow, error) {
	rows, err := q.db.Query(ctx, requeueStalled, arg.StaleSecs, arg.MaxRequeues)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RequeueStalledRow
	for rows.Next() {
		var i RequeueStalledRow
		if err := rows.Scan(&i.ID, &i.RunID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

